#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || n < 1) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    unsigned long long cur = (unsigned long long)n;
    long steps = 0;
    while (cur != 1ULL) {
        if (steps > 999999L) {
            puts("STEP_LIMIT_EXCEEDED");
            return 0;
        }
        if (cur > 1000000000000000ULL) {
            puts("OVERFLOW_GUARD");
            return 0;
        }
        if ((cur & 1ULL) == 0ULL) {
            cur >>= 1;
        } else {
            cur = cur * 3ULL + 1ULL;
        }
        ++steps;
    }
    printf("n=%ld steps=%ld\n", n, steps);
    return 0;
}
